import React, { useState } from 'react';

const NewDeploymentForm = () => (
  <div>
    <h2>New Deployment</h2>
    <form>
      <div>
        <label htmlFor="title">Title</label>
        <input type="text" id="title" name="title" placeholder="change summary ..." />
      </div>
      <div>
        <label htmlFor="sourceOrg">Source Org</label>
        <select id="sourceOrg" name="sourceOrg">
          <option value="">select</option>
          {/* Add more options here */}
        </select>
      </div>
      <div>
        <label htmlFor="targetOrg">Target Org</label>
        <select id="targetOrg" name="targetOrg">
          <option value="">select</option>
          {/* Add more options here */}
        </select>
      </div>
      {/* Add more fields here if needed */}
      <button type="submit">Save</button>
      <button type="button" onClick={() => setShowForm(false)}>Cancel</button>
    </form>
  </div>
);

const DeploymentsPage = () => {
  const [showForm, setShowForm] = useState(false);

  return (
    <div>
      <h1>Deployments</h1>
      {showForm ? (
        <NewDeploymentForm />
      ) : (
        <>
          <button onClick={() => setShowForm(true)}>New Deployment</button>
          {/* Add the list of deployments here */}
        </>
      )}
    </div>
  );
};

export default DeploymentsPage;
